import { describe, it, expect } from 'vitest';
import {
  signAll,
  signPayload,
  signPayloadV2,
  verifySignature,
  verifySignatureV2,
} from './signature';

describe('signPayload', () => {
  it('is a hex HMAC-SHA256 of the body', () => {
    expect(signPayload('whsec_test', '{"id":1}')).toBe(
      '6b0a3b1e2a8f4d6a0f8c3e1d9b7a5c4e2f0d8b6a4c2e0f9d7b5a3c1e9f7d5b3a',
    );
  });

  it('round-trips through verifySignature', () => {
    const sig = signPayload('whsec_test', 'hello');
    expect(verifySignature('whsec_test', 'hello', sig)).toBe(true);
    expect(verifySignature('whsec_other', 'hello', sig)).toBe(false);
  });
});

describe('signAll', () => {
  it('emits one v1 entry per secret', () => {
    const header = signAll(['whsec_new', 'whsec_old'], 'hello');
    const [a, b] = header.split(',');
    expect(a).toBe(signPayload('whsec_new', 'hello'));
    expect(b).toBe(signPayload('whsec_old', 'hello'));
  });
});

describe('v2 signatures', () => {
  const t = 1_760_000_000;

  it('formats the header as t=<ts>,v1=<hex>', () => {
    expect(signPayloadV2('whsec_test', '{"id":1}', t)).toMatch(/^t=1760000000,v1=[0-9a-f]{64}$/);
  });

  it('verifies within the tolerance window', () => {
    const header = signPayloadV2('whsec_test', 'hello', t);
    expect(verifySignatureV2('whsec_test', 'hello', header, t + 299)).toBe(true);
    expect(verifySignatureV2('whsec_other', 'hello', header, t + 1)).toBe(false);
  });

  it('rejects stale timestamps', () => {
    const header = signPayloadV2('whsec_test', 'hello', t);
    expect(verifySignatureV2('whsec_test', 'hello', header, t + 301)).toBe(false);
  });
});

